# Fig 7 A5: detectable GALNT-system genes in the two Visium datasets (spec A5; list 1 = frozen all-spot criterion, list 2 = post hoc epithelial-spot criterion A5b).
suppressPackageStartupMessages({library(Seurat); library(data.table); library(Matrix); library(FNN); library(metafor); library(lme4); library(lmerTest)})
root <- "${PROJECT_ROOT}"; out <- file.path(root, "04_results/2026-10-12_Figure7_GALNT_run01")
fam <- c(paste0("GALNT", 1:18), "GALNTL5", "GALNTL6", "C1GALT1", "C1GALT1C1"); ALIAS <- c(GALNT15 = "GALNTL2", GALNT16 = "GALNTL1", GALNT17 = "WBSCR17", GALNT18 = "GALNTL4")
x <- readRDS("${PANIN_ROOT}/01_raw/Elhossiny_CancerDiscovery_2026/spatial.rds"); if (length(Layers(x[["Spatial"]], search = "counts")) > 1) x[["Spatial"]] <- JoinLayers(x[["Spatial"]])
cn <- GetAssayData(x, assay = "Spatial", layer = "counts"); rn <- rownames(cn); gm <- sapply(fam, function(gg) if (gg %in% rn) gg else if (!is.na(ALIAS[gg]) && ALIAS[gg] %in% rn) ALIAS[[gg]] else NA); present <- fam[!is.na(gm)]
md <- as.data.table(x@meta.data, keep.rownames = "spot"); W <- as.data.table(t(as.matrix(GetAssayData(x, assay = "RCTD_sub_wts", layer = "data"))), keep.rownames = "spot"); md <- merge(md, W, by = "spot"); md <- md[match(colnames(cn), spot)]
md[, lc := log10(nCount_Spatial)]; ln <- function(spots) { m <- cn[, spots, drop = FALSE]; m@x <- m@x / rep(colSums(m), diff(m@p)) * 1e4; m@x <- log1p(m@x); m }
## D0 detectability (all spots; epithelial spots)
frac <- function(spots) sapply(present, function(gn) mean(cn[gm[[gn]], spots] > 0))
sp <- fread(file.path(root, "02_intermediate/fig6_visium/spots_galnt_annot.csv.gz")); sp <- sp[lib >= 500]; fp <- function(d) sapply(present, function(gn) mean(d[[gn]] > 0))
epiE <- md[tissue == "PDAC" & `Tumor-Epithelial` >= 0.5]$spot
det <- data.table(gene = present, E_all = frac(md$spot), P_all = fp(sp), E_epi = frac(epiE), P_epi = fp(sp[paningrade %in% c("normal", "low_grade", "high_grade")]))
det[, `:=`(detectable_all = E_all >= 0.3 & P_all >= 0.3, detectable_epi = E_epi >= 0.3 & P_epi >= 0.3)]; fwrite(det, file.path(out, "H7f_detectability.csv")); print(det[order(-E_epi)][, lapply(.SD, function(v) if (is.numeric(v)) round(v, 3) else v)])
lists <- list(frozen_all_spot = det[detectable_all == TRUE]$gene, posthoc_epithelial = det[detectable_epi == TRUE]$gene); print(lists)
pd <- md[tissue == "PDAC"]; Lp <- ln(pd$spot); rownames(Lp) <- rn; ct <- setdiff(colnames(W), "spot")
myc <- c("TAGLN", "MYL9", "TPM1", "TPM2", "MMP11", "POSTN", "HOPX", "ACTA2"); ic <- c("IL6", "CXCL8", "CXCL1", "CXCL2", "CCL2", "CXCL12", "CFD", "LMNA", "DPT", "HAS1", "HAS2", "AGTR1"); sc_ <- function(gg) colMeans(t(scale(t(as.matrix(Lp[intersect(gg, rn), ]))))); pd[, `:=`(myCAF = sc_(myc), iCAF = sc_(ic))]; tg <- c(ct, "myCAF", "iCAF")
d1 <- md[(SpatialDomain == "Ducts" & tissue %in% c("Healthy", "AdjNormal")) | (tissue == "PDAC" & SpatialDomain %in% c("PanIN/GLTumor", "PDTumor"))]; d1[, gstep := fifelse(SpatialDomain == "Ducts", 0L, fifelse(SpatialDomain == "PanIN/GLTumor", 1L, 2L))]; d1[, grp := factor(gstep, 0:2, c("Normal duct", "PanIN/GL tumor", "PD tumor"))]
cat("D1 spots:\n"); print(d1[, .N, by = grp]); L1 <- ln(d1$spot)
meta <- function(per) { per <- per[is.finite(rho)]; per[, `:=`(z = atanh(rho), se = 1 / sqrt(n - 4))]; r <- rma(yi = per$z, sei = per$se, method = "DL"); data.table(k = nrow(per), pooled_rho = tanh(r$b[1]), lo = tanh(r$ci.lb), hi = tanh(r$ci.ub), p = r$pval, sections_pos = sum(per$rho > 0)) }
feats <- c(ct, "myCAF", "iCAF"); pd[, `:=`(isT = SpatialDomain %in% c("PanIN/GLTumor", "PDTumor"), epi_w = `Tumor-Epithelial`)]
nich <- function(d) { xy <- cbind(d$pxl_col_in_fullres, d$pxl_row_in_fullres); nn <- get.knn(xy, k = 6)$nn.index; F <- as.data.table(sapply(feats, function(f) rowMeans(matrix(d[[f]][nn], ncol = 6)))); F[, purity := rowMeans(matrix(d$isT[nn] * 1, ncol = 6))]; cbind(d[, .(spot, sample_Id, lc, epi_w)], F) }
N <- rbindlist(lapply(unique(pd$sample_Id), function(s) nich(pd[sample_Id == s]))); N <- N[epi_w >= 0.5]; fe <- c(feats, "purity")
for (ln_ in names(lists)) { dg <- lists[[ln_]]; sfx <- paste0("_", ln_); if (!length(dg)) next; cat("\n########", ln_, ":", dg, "\n")
  r1 <- rbindlist(lapply(dg, function(gn) { d <- copy(d1); d[, y := as.numeric(L1[gm[[gn]], ])]; m <- lmer(y ~ gstep + lc + (1 | sample_Id), d); s <- coef(summary(m)); mc <- lmer(y ~ grp + lc + (1 | sample_Id), d); sc <- coef(summary(mc))
    data.table(gene = gn, slope_per_step = s["gstep", "Estimate"], se = s["gstep", "Std. Error"], p = s["gstep", "Pr(>|t|)"], PanINGL_vs_normal = sc["grpPanIN/GL tumor", "Estimate"], p_PanINGL = sc["grpPanIN/GL tumor", "Pr(>|t|)"], PD_vs_normal = sc["grpPD tumor", "Estimate"], p_PD = sc["grpPD tumor", "Pr(>|t|)"], mean_normal = mean(d[gstep == 0]$y), mean_PanINGL = mean(d[gstep == 1]$y), mean_PD = mean(d[gstep == 2]$y)) })); r1[, BH := p.adjust(p, "BH")]
  fwrite(r1, file.path(out, paste0("H7f_lesion_axis_Elhossiny", sfx, ".csv"))); cat("D1 lesion axis (normal duct -> PanIN/GL -> PD):\n"); print(r1[, lapply(.SD, function(v) if (is.numeric(v)) signif(v, 3) else v)][, .(gene, slope_per_step, p, BH, PanINGL_vs_normal, PD_vs_normal, mean_normal, mean_PanINGL, mean_PD)])
  r2 <- rbindlist(lapply(dg, function(gn) { pd[, y := as.numeric(Lp[gm[[gn]], ])]; rbindlist(lapply(tg, function(t) cbind(gene = gn, target = t, meta(pd[, { a <- resid(lm(rank(y) ~ lc)); b <- resid(lm(rank(get(t)) ~ lc)); .(rho = cor(a, b), n = .N) }, by = sample_Id])))) })); r2[, BH := p.adjust(p, "BH"), by = gene]; fwrite(r2, file.path(out, paste0("H7f_colocalization", sfx, ".csv")))
  cat("D2 strongest co-localisations per gene:\n"); print(r2[, .SD[order(-abs(pooled_rho))][1:3], by = gene][, .(gene, target, pooled_rho = round(pooled_rho, 3), BH = signif(BH, 2), sections_pos)])
  r3 <- rbindlist(lapply(dg, function(gn) { N[, y := as.numeric(Lp[gm[[gn]], spot])]; rbindlist(lapply(fe, function(f) cbind(gene = gn, feature = f, meta(N[, { a <- resid(lm(rank(y) ~ lc + epi_w)); b <- resid(lm(rank(get(f)) ~ lc + epi_w)); .(rho = cor(a, b), n = .N) }, by = sample_Id])))) })); r3[, BH := p.adjust(p, "BH"), by = gene]; fwrite(r3, file.path(out, paste0("H7f_epithelial_niche", sfx, ".csv")))
  cat("D3 strongest niche associations per gene:\n"); print(r3[, .SD[order(-abs(pooled_rho))][1:3], by = gene][, .(gene, feature, pooled_rho = round(pooled_rho, 3), BH = signif(BH, 2), sections_pos)]) }
